        },
        {
          "gap": "The economic team and delegated authority beyond Nabiullina are not fully mapped.",
          "lenses": ["5B.2", "5B.7"],
          "best_source_or_query_direction": "Personnel decrees and contemporaneous reporting on Siluanov, Reshetnikov, and wartime fiscal decision-making.",
